package codegen

import (
	"sort"
	"strings"
	"testing"

	"ghp/src/internal/ast"
	"ghp/src/internal/goimports"
)

// legacyWriteImports is the import-block writer Assemble used before the
// renderer moved to the shared goimports package (see git history for
// commit that introduced this test). It is kept here only as the oracle
// for TestImportBlockMatchesLegacyRenderer: the refactor's promise is that
// the generated bytes do not change, and a characterization test is the
// only way to hold the extractor to that.
func legacyWriteImports(imports map[string]ast.ImportPath) string {
	var b strings.Builder

	paths := make([]string, 0, len(imports))
	for path := range imports {
		paths = append(paths, path)
	}
	sort.Strings(paths)

	b.WriteString("import (\n")
	for _, path := range paths {
		if alias := imports[path].Alias; alias != "" {
			b.WriteString("\t" + alias + " ")
			b.WriteString(quote(path))
		} else {
			b.WriteString("\t")
			b.WriteString(quote(path))
		}
		b.WriteString("\n")
	}
	b.WriteString(")\n\n")
	return b.String()
}

// quote mirrors %q for the plain import paths in these fixtures (no
// escapes needed), keeping the oracle free of fmt so it reads as the
// algorithm it documents.
func quote(s string) string {
	return `"` + s + `"`
}

// TestImportBlockMatchesLegacyRenderer is the differential check for the
// pages/codegen import-renderer dedup: for a broad set of import sets, the
// new specsOf+goimports.BlockWithNewline path must produce exactly the
// bytes the old writeImports did. Any divergence is a behavior change
// smuggled in under a refactor.
func TestImportBlockMatchesLegacyRenderer(t *testing.T) {
	tests := []struct {
		name    string
		imports map[string]ast.ImportPath
	}{
		{
			name:    "single path",
			imports: map[string]ast.ImportPath{"net/http": {Path: "net/http"}},
		},
		{
			name: "two plain paths",
			imports: map[string]ast.ImportPath{
				"net/http": {Path: "net/http"},
				"io":       {Path: "io"},
			},
		},
		{
			name: "aliased and plain mixed",
			imports: map[string]ast.ImportPath{
				"net/http": {Path: "net/http"},
				"strings":  {Alias: "s", Path: "strings"},
				"fmt":      {Path: "fmt"},
			},
		},
		{
			name: "single aliased path",
			imports: map[string]ast.ImportPath{
				"strings": {Alias: "s", Path: "strings"},
			},
		},
		{
			name: "reverse insertion order still sorts",
			imports: map[string]ast.ImportPath{
				"z/z": {Path: "z/z"},
				"a/a": {Path: "a/a"},
				"m/m": {Path: "m/m"},
			},
		},
		{
			name:    "empty set",
			imports: map[string]ast.ImportPath{},
		},
		{
			name: "all managed packages",
			imports: map[string]ast.ImportPath{
				"net/http": {Path: "net/http"},
				"fmt":      {Path: "fmt"},
				"html":     {Path: "html"},
				"io":       {Path: "io"},
			},
		},
		{
			name: "deep third-party path",
			imports: map[string]ast.ImportPath{
				"github.com/acme/site/internal/db": {Alias: "db", Path: "github.com/acme/site/internal/db"},
				"net/http":                         {Path: "net/http"},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := goimports.Block(specsOf(tt.imports))
			want := legacyWriteImports(tt.imports)

			if got != want {
				t.Errorf("new renderer diverges from legacy\nnew:  %q\nold:  %q", got, want)
			}
		})
	}
}
